args.command:
node -e "
const zones = ['America/Los_Angeles','Asia/Makassar','Europe/Zurich','Asia/Kolkata','Asia/Kathmandu','Pacific/Auckland','America/New_York','Pacific/Honolulu'];
const dates = ['2026-09-29T18:00:00Z','2026-01-15T16:00:00Z','2026-07-01T16:00:00Z'];
function off(tz, iso) {
  const date = new Date(iso);
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: '2-digit', minute: '2-digit', timeZoneName: 'longOffset', hourCycle: 'h23' }).formatToParts(date);
  const name = parts.find(p => p.type === 'timeZoneName')?.value;
  const hour = parts.find(p => p.type === 'hour')?.value;
  const short = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'short' }).formatToParts(date).find(p => p.type === 'timeZoneName')?.value;
  return { tz, iso, name, short, hour };
}
for (const iso of dates) for (const tz of zones) console.log(JSON.stringify(off(tz, iso)));
" && node -v && pnpm -v

