  id: string;
  name: string;
  country: string;
  region: Region;
  timeZone: string;
  aliases?: readonly string[];
};

export type Mode = 'meeting' | 'base';

export type TimeFormat = '12h' | '24h';

export type CellState = 'sleep' | 'awake' | 'overlap';

