  overflow: auto;
  list-style: none;
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  box-shadow: 0 16px 40px rgba(20, 33, 27, 0.12);
}

.group-label {
  padding: 8px 10px 4px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.option {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 8px 10px;
  border-radius: 10px;
  text-align: left;
}

.option[aria-selected='true'], .option:hover { background: #e5f5eb; }
.option-city { display: block; font-weight: 700; }
.option-country { display: block; color: var(--muted); font-size: 12px; }
.option-off { color: #3e5147; font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.menu-empty { padding: 12px 10px; color: var(--muted); font-size: 13px; }

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  margin: 2px 0 14px;
}

.summary-base { display: block; }

.summary-lead {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.summary-where { color: var(--muted); font-size: 13px; font-weight: 600; }

.badge {
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--overlap);
