  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.banner-warn {
  margin: 0;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--warn-bg);
  color: var(--warn);
  font-size: 14px;
  font-weight: 700;
}

.base-kicker { margin: 0 0 4px; }
.base-list { margin: 0; padding: 0; list-style: none; }

.base-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.base-name { font-weight: 700; }
.base-detail { color: #3e5147; font-variant-numeric: tabular-nums; }
.base-warn { color: var(--warn); font-weight: 700; }

.tick {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.tick-main { font-size: 13px; font-weight: 650; letter-spacing: -0.03em; white-space: nowrap; }
.tick-sub {
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.72;
}

.day-delta { margin-left: 1px; font-size: 8px; font-weight: 700; }

.cell {
  display: grid;
  place-items: center;
  min-height: 52px;
  border-radius: 8px;
  cursor: default;
}

.cell[data-state='sleep'] { background: var(--sleep); color: var(--sleep-ink); }
.cell[data-state='awake'] {
  background: var(--awake);
  color: var(--ink);
  box-shadow: inset 0 0 0 1px #e3e8e1;
}
.cell[data-state='overlap'] { background: var(--overlap); color: var(--overlap-ink); }
.cell[data-state='overlap'] .tick-main { font-weight: 700; }
.cell[data-state='overlap'] .tick-sub { opacity: 0.92; }

.cell.is-hot { outline: 2px solid var(--ink); outline-offset: -2px; }
.cell[data-state='overlap'].is-hot { outline-color: #f3f0e6; }
.cell[data-state='awake'].is-now { box-shadow: inset 0 3px 0 var(--ref), inset 0 0 0 1px #e3e8e1; }
.cell[data-state='sleep'].is-now,
.cell[data-state='overlap'].is-now { box-shadow: inset 0 3px 0 var(--ref); }

/* Desktop: cities are rows, reference hours are columns. One shared grid so hours line up. */
.d-board {
  display: grid;
  grid-template-columns: 200px repeat(24, minmax(46px, 1fr)) 40px;
  column-gap: 3px;
  row-gap: 6px;
  overflow: auto;
  max-height: calc(100dvh - 300px);
  padding-bottom: 6px;
}

.d-board > * { min-width: 0; }

.d-corner, .d-city {
  position: sticky;
  left: 0;
  z-index: 4;
  background: var(--paper);
}

.d-hour, .d-corner, .d-end {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--paper);
}

.d-corner { z-index: 6; }

.d-end, .d-remove {
  position: sticky;
  right: 0;
  z-index: 4;
  background: var(--paper);
}

.d-end { z-index: 6; }

.d-corner, .d-city {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 2px;
  min-height: 72px;
  padding: 8px 10px 8px 12px;
  text-align: left;
}

.d-corner::after, .d-city::after {
  content: "";
  position: absolute;
  top: 0;
  right: -3px;
  bottom: -6px;
  width: 3px;
  background: var(--paper);
}

.d-city[data-ref='true'] { box-shadow: inset 3px 0 0 var(--ref); }
.d-city[data-ref='false']:hover .city-name { text-decoration: underline; text-underline-offset: 3px; }

.d-hour, .d-end, .d-remove {
  display: grid;
  place-items: center;
  min-height: 44px;
}

.d-hour { border-bottom: 1px solid var(--line); }
.d-hour.is-now { box-shadow: inset 0 -3px 0 var(--ref); }
.axis-overlap .tick { color: var(--overlap); }
.axis-sleep .tick { color: #8b958e; }
.axis-overlap .tick-main { font-weight: 700; }

.name-row { display: flex; align-items: center; gap: 6px; min-width: 0; }
.city-name { font-size: 15px; font-weight: 700; letter-spacing: -0.02em; }
.city-sub, .city-now { color: var(--muted); font-size: 12px; }
.city-now { font-variant-numeric: tabular-nums; }

.ref-badge {
  flex: none;
  padding: 2px 5px;
  border: 1px solid currentColor;
  border-radius: 999px;
  color: var(--ref);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  line-height: 1.2;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  color: var(--muted);
}

.icon-btn:hover { background: #f6ddd4; color: var(--warn); }

.empty {
  padding: 48px 16px;
  border: 1px dashed #c9d2c8;
  border-radius: 16px;
  color: var(--muted);
  text-align: center;
}

.foot {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.legend li { display: flex; align-items: center; }

.swatch {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 6px;
  border-radius: 3px;
}

.swatch[data-state='overlap'] { background: var(--overlap); }
.swatch[data-state='awake'] { background: white; box-shadow: inset 0 0 0 1px #cfd6ce; }
.swatch[data-state='sleep'] { background: var(--sleep); }

.hint {
  margin: 0;
  color: #24352c;
  font-size: 14px;
  font-weight: 700;
}

/* Mobile: cities are columns, reference hours are rows. Separate grid, not a reflow of the desktop one. */
.m-board {
  display: grid;
  gap: 4px;
  overflow: auto;
  max-height: calc(100dvh - 280px);
  padding-bottom: 8px;
}

.m-corner, .m-city {
  position: sticky;
  top: 0;
  z-index: 4;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.m-hour {
  position: sticky;
  left: 0;
  z-index: 3;
  display: grid;
  place-items: center;
  min-height: 48px;
  background: var(--paper);
}

.m-corner {
  left: 0;
  z-index: 6;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 2px;
  padding: 8px;
}

.m-city {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 108px;
  padding: 8px;
}

.m-city[data-ref='true'] { box-shadow: inset 0 3px 0 var(--ref); }

.m-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
}

.m-top .icon-btn { margin-left: auto; }

.city-hit {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  text-align: left;
}

.m-hour.is-now { box-shadow: inset 3px 0 0 var(--ref); }
.corner-city { font-weight: 700; letter-spacing: -0.02em; }

@media (max-width: 767px) {
  .hero-inner { flex-direction: column; align-items: stretch; padding: 20px 0 18px; }
  .modes, .mode { width: 100%; min-width: 0; }
  .controls { grid-template-columns: 1fr; }
  .panel { padding: 12px; border-radius: 16px; }
  .shell { width: min(1480px, calc(100% - 20px)); }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
}

