      };
    });
    const cities = [...document.querySelectorAll('[data-layout="desktop"] [data-city]')].map((node) => ({
      id: node.dataset.city,
      ref: node.dataset.ref,
      y: Math.round(node.getBoundingClientRect().y),
      text: node.innerText,
    }));
    const board = document.querySelector('.d-board').getBoundingClientRect();
    const removes = [...document.querySelectorAll('.d-remove')].map((node) => {
      const rect = node.getBoundingClientRect();
