    const overlap = getComputedStyle(document.querySelector('[data-state="overlap"]'));
    const sleep = getComputedStyle(document.querySelector('[data-state="sleep"]'));
    const awake = getComputedStyle(document.querySelector('[data-state="awake"]'));
    return {
