.option-off { color: #3e5147; font-size: 12px; font-variant-numeric: tabular-nums; white-space: nowrap; }
.menu-empty { padding: 12px 10px; color: var(--muted); font-size: 13px; }

.summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px 10px;
  margin: 2px 0 14px;
}

.summary-base { display: block; }

.summary-lead {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.summary-where { color: var(--muted); font-size: 13px; font-weight: 600; }

.badge {
  padding: 5px 10px;
  border-radius: 999px;
  background: var(--overlap);
  color: var(--overlap-ink);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: -0.01em;
}

.banner-warn {
  margin: 0;
  padding: 10px 12px;
  border-radius: 12px;
  background: var(--warn-bg);
  color: var(--warn);
  font-size: 14px;
  font-weight: 700;
}

.base-kicker { margin: 0 0 4px; }
.base-list { margin: 0; padding: 0; list-style: none; }

.base-line {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 8px 0;
  border-top: 1px solid var(--line);
}

.base-name { font-weight: 700; }
.base-detail { color: #3e5147; font-variant-numeric: tabular-nums; }
.base-warn { color: var(--warn); font-weight: 700; }

.tick {
  display: flex;
  flex-direction: column;
  align-items: center;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}

.tick-main { font-size: 13px; font-weight: 650; letter-spacing: -0.03em; white-space: nowrap; }
.tick-sub {
  margin-top: 3px;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  opacity: 0.72;
}

.day-delta { margin-left: 1px; font-size: 8px; font-weight: 700; }

.cell {
  display: grid;
  place-items: center;
  min-height: 52px;
  border-radius: 8px;
  cursor: default;
