.d-hour { border-bottom: 1px solid var(--line); }
.d-hour.is-now { box-shadow: inset 0 -3px 0 var(--ref); }
.axis-overlap .tick { color: var(--overlap); }
.axis-sleep .tick { color: #8b958e; }
.axis-overlap .tick-main { font-weight: 700; }

.name-row { display: flex; align-items: center; gap: 6px; min-width: 0; }
.city-name { font-size: 15px; font-weight: 700; letter-spacing: -0.02em; }
.city-sub, .city-now { color: var(--muted); font-size: 12px; }
.city-now { font-variant-numeric: tabular-nums; }

.ref-badge {
  flex: none;
