  font-weight: 800;
  letter-spacing: 0.14em;
  line-height: 1.2;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  color: var(--muted);
}

.icon-btn:hover { background: #f6ddd4; color: var(--warn); }

.empty {
  padding: 48px 16px;
  border: 1px dashed #c9d2c8;
  border-radius: 16px;
  color: var(--muted);
  text-align: center;
}

.foot {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.legend li { display: flex; align-items: center; }

