  line-height: 0.92;
}

.modes {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  padding: 4px;
  border-radius: 14px;
  background: #24352c;
}

.mode {
  min-width: 148px;
  padding: 8px 14px;
  border-radius: 10px;
  text-align: left;
  color: #d7e3db;
}

.mode[aria-checked='true'] {
  background: #f3f0e6;
  color: var(--ink);
}

.mode-name { display: block; font-size: 14px; font-weight: 700; }
.mode-sub { display: block; margin-top: 2px; font-size: 11px; font-weight: 500; opacity: 0.72; }

.panel {
  margin: 22px 0 32px;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 22px;
  box-shadow: var(--shadow);
}

.controls {
  display: grid;
  grid-template-columns: minmax(260px, 1fr) minmax(280px, 340px);
  gap: 18px;
  align-items: start;
  margin-bottom: 14px;
}

.field-label, .settings legend, .kicker, .base-kicker {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}

.picker { position: relative; z-index: 8; }

.picker input, .settings select {
  width: 100%;
  height: 42px;
  margin-top: 6px;
  padding: 0 12px;
  border: 1px solid #d5ddd4;
  border-radius: 12px;
  background: white;
}

.picker input { padding-right: 12px; }

.settings {
  margin: 0;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--sheet);
}

.settings legend { padding: 0 4px; }

.window-readout {
  margin: 2px 0 10px;
  font-family: var(--serif);
  font-size: 28px;
  font-weight: 560;
  letter-spacing: -0.03em;
  line-height: 1;
}

.setting-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.setting-row label {
  display: flex;
  flex-direction: column;
  gap: 0;
  font-size: 12px;
  font-weight: 650;
  color: var(--muted);
}

