  max-height: calc(100dvh - 300px);
  padding-bottom: 6px;
}

.d-board > * { min-width: 0; }

.d-corner, .d-city {
  position: sticky;
  left: 0;
  z-index: 4;
  background: var(--paper);
}

.d-hour, .d-corner, .d-end {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--paper);
}

.d-corner { z-index: 6; }

.d-end, .d-remove {
  position: sticky;
  right: 0;
  z-index: 4;
  background: var(--paper);
}

.d-end { z-index: 6; }

