  font-weight: 800;
  letter-spacing: 0.14em;
  line-height: 1.2;
}

.icon-btn {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  color: var(--muted);
}

.icon-btn:hover { background: #f6ddd4; color: var(--warn); }

.empty {
  padding: 48px 16px;
  border: 1px dashed #c9d2c8;
  border-radius: 16px;
  color: var(--muted);
  text-align: center;
}

.foot {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.legend {
  display: flex;
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

.legend li { display: flex; align-items: center; }

.swatch {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 6px;
  border-radius: 3px;
}

.swatch[data-state='overlap'] { background: var(--overlap); }
.swatch[data-state='awake'] { background: white; box-shadow: inset 0 0 0 1px #cfd6ce; }
.swatch[data-state='sleep'] { background: var(--sleep); }

.hint {
  margin: 0;
  color: #24352c;
  font-size: 14px;
  font-weight: 700;
}

/* Mobile: cities are columns, reference hours are rows. Separate grid, not a reflow of the desktop one. */
.m-board {
  display: grid;
  gap: 4px;
  overflow-x: auto;
  padding-bottom: 8px;
}

.m-corner, .m-city {
  position: sticky;
  top: 0;
  z-index: 4;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.m-hour {
  position: sticky;
  left: 0;
  z-index: 3;
  display: grid;
  place-items: center;
  min-height: 48px;
  background: var(--paper);
}

.m-corner {
  left: 0;
  z-index: 6;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 2px;
  padding: 8px;
}

.m-city {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-height: 96px;
  padding: 8px;
}

.m-city .city-name { font-size: 14px; line-height: 1.15; }
.m-city .city-sub, .m-city .city-now { overflow-wrap: anywhere; }

.m-city[data-ref='true'] { box-shadow: inset 0 3px 0 var(--ref); }

.m-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 28px;
}

.m-top .icon-btn { margin-left: auto; }

.city-hit {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  text-align: left;
}

.m-hour.is-now { box-shadow: inset 3px 0 0 var(--ref); }
.corner-city { font-weight: 700; letter-spacing: -0.02em; }

@media (max-width: 767px) {
  .hero-inner { flex-direction: column; align-items: stretch; padding: 20px 0 18px; }
