  .controls { grid-template-columns: 1fr; }
  .panel { padding: 12px; border-radius: 16px; }
  .shell { width: min(1480px, calc(100% - 20px)); }
}

@media (prefers-reduced-motion: reduce) {
  * { scroll-behavior: auto !important; }
}

