import { spawn } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const profile = await mkdtemp(join(tmpdir(), 'tz-chrome-'));
const port = 9342;
const chrome = spawn(chromePath, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check',
  `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, 'about:blank',
], { stdio: 'ignore' });

async function waitJson(url) {
  for (let i = 0; i < 50; i += 1) {
    try {
      const response = await fetch(url);
      if (response.ok) return await response.json();
    } catch { /* booting */ }
    await delay(100);
  }
  throw new Error('chrome timeout');
}

const version = await waitJson(`http://127.0.0.1:${port}/json/version`);
const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
let seq = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
});
function send(method, params = {}, sessionId) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, (message) => {
      if (message.error) reject(new Error(`${method} ${JSON.stringify(message.error)}`));
      else resolve(message.result);
    });
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    ws.send(JSON.stringify(payload));
  });
}
const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
const page = (method, params) => send(method, params, sessionId);
await page('Page.enable');
await page('Runtime.enable');
async function evaluate(expression) {
  const result = await page('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text);
  return result.result.value;
}
async function shot(name) {
  const { data } = await page('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true });
  await writeFile(new URL(`../${name}`, import.meta.url), Buffer.from(data, 'base64'));
}
async function viewport(width, height) {
  await page('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: width < 768 });
}

const report = {};
try {
  await viewport(820, 900);
  await page('Page.navigate', { url: 'http://localhost:9350/' });
  await evaluate(`new Promise((resolve) => {
    const start = Date.now();
    const id = setInterval(() => {
      if (document.querySelector('.cell[data-state="overlap"]') || Date.now() - start > 8000) {
        clearInterval(id); resolve(true);
      }
    }, 40);
  })`);
  report.narrow = await evaluate(`(() => {
    const board = document.querySelector('.d-board');
    const boardRect = board.getBoundingClientRect();
    const hours = [...document.querySelectorAll('.d-hour')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { hour: Number(node.dataset.hour), left: Math.round(rect.left), right: Math.round(rect.right), visible: rect.right > boardRect.left + 8 && rect.left < boardRect.right - 8 };
    });
    const removes = [...document.querySelectorAll('.d-remove')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { left: Math.round(rect.left), right: Math.round(rect.right), inBoard: rect.left >= boardRect.left && rect.right <= boardRect.right + 1 };
    });
    const overlap = getComputedStyle(document.querySelector('.cell[data-state="overlap"]'));
    const sleep = getComputedStyle(document.querySelector('.cell[data-state="sleep"]'));
    const awake = getComputedStyle(document.querySelector('.cell[data-state="awake"]'));
    return {
      board: { width: Math.round(boardRect.width), scroll: board.scrollWidth, client: board.clientWidth },
      visibleHours: hours.filter((hour) => hour.visible).map((hour) => hour.hour),
      hiddenHours: hours.filter((hour) => !hour.visible).map((hour) => hour.hour),
      removes,
      colors: { overlap: overlap.backgroundColor, sleep: sleep.backgroundColor, awake: awake.backgroundColor, overlapColor: overlap.color },
      hourCount: document.querySelectorAll('.d-hour').length,
      cellCount: document.querySelectorAll('.d-board .cell').length,
    };
  })()`);
  await shot('verify-narrow.png');

  await viewport(390, 844);
  await delay(80);
  report.mobile = await evaluate(`(() => {
    const board = document.querySelector('.m-board');
    const hours = [...document.querySelectorAll('.m-hour')];
    const cities = [...document.querySelectorAll('.m-city')];
    const ys = hours.map((node) => Math.round(node.getBoundingClientRect().y));
    const cityBoxes = cities.map((node) => {
      const rect = node.getBoundingClientRect();
      const name = node.querySelector('.city-name');
      return {
        id: node.dataset.city,
        text: name?.textContent,
        width: Math.round(rect.width),
        nameScroll: name?.scrollWidth,
        nameClient: name?.clientWidth,
        x: Math.round(rect.x),
      };
    });
    return {
      desktop: Boolean(document.querySelector('.d-board')),
      hourCount: hours.length,
      increasing: ys.every((y, index) => index === 0 || y > ys[index - 1]),
      firstY: ys[0],
      lastY: ys.at(-1),
      cityBoxes,
      boardScroll: board.scrollWidth,
      boardClient: board.clientWidth,
      hint: document.querySelector('.hint')?.textContent,
      title: document.title,
    };
  })()`);
  await shot('verify-mobile-default.png');

  await evaluate('window.scrollTo(0, 900)');
  await delay(50);
  report.stuck = await evaluate(`(() => {
    const header = document.querySelector('.m-city');
    const hour = document.querySelector('.m-hour[data-hour="18"]');
    return {
      headerTop: Math.round(header.getBoundingClientRect().top),
      hour18Top: hour ? Math.round(hour.getBoundingClientRect().top) : null,
      scrollY: Math.round(window.scrollY),
    };
  })()`);
  await shot('verify-mobile-scrolled.png');
  console.log(JSON.stringify(report, null, 2));
} finally {
  chrome.kill();
  ws.close();
  await rm(profile, { recursive: true, force: true }).catch(() => {});
}

