  display: grid;
  grid-template-columns: 200px repeat(24, minmax(46px, 1fr)) 40px;
  column-gap: 3px;
  row-gap: 6px;
  overflow: auto;
  max-height: calc(100dvh - 300px);
  padding-bottom: 6px;
}

.d-board > * { min-width: 0; }

.d-corner, .d-city {
  position: sticky;
  left: 0;
  z-index: 4;
  background: var(--paper);
}

.d-hour, .d-corner, .d-end {
  position: sticky;
  top: 0;
  z-index: 3;
  background: var(--paper);
}

.d-corner { z-index: 6; }

.d-remove, .d-end { background: var(--paper); }

.d-corner, .d-city {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 2px;
  min-height: 72px;
  padding: 8px 10px 8px 12px;
  text-align: left;
}

.d-corner::after, .d-city::after {
  content: "";
  position: absolute;
  top: 0;
  right: -3px;
  bottom: -6px;
  width: 3px;
  background: var(--paper);
}

.d-city[data-ref='true'] { box-shadow: inset 3px 0 0 var(--ref); }
