import { spawn } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const profile = await mkdtemp(join(tmpdir(), 'tz-chrome-'));
const port = 9341;
const chrome = spawn(
  chromePath,
  [
    '--headless=new',
    '--disable-gpu',
    '--no-first-run',
    '--no-default-browser-check',
    `--remote-debugging-port=${port}`,
    `--user-data-dir=${profile}`,
    'about:blank',
  ],
  { stdio: 'ignore' },
);

const failures = [];
const logs = [];

function assert(cond, message) {
  if (!cond) failures.push(message);
  else logs.push(`ok ${message}`);
}

async function waitJson(url) {
  for (let i = 0; i < 50; i += 1) {
    try {
      const response = await fetch(url);
      if (response.ok) return await response.json();
    } catch {
      /* chrome still booting */
    }
    await delay(100);
  }
  throw new Error(`timed out waiting for ${url}`);
}

const version = await waitJson(`http://127.0.0.1:${port}/json/version`);
const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});

let seq = 0;
const pending = new Map();
const exceptions = [];
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
  if (message.method === 'Runtime.exceptionThrown') {
    exceptions.push(message.params.exceptionDetails?.exception?.description ?? message.params.exceptionDetails?.text);
  }
});

function send(method, params = {}, sessionId) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, (message) => {
      if (message.error) reject(new Error(`${method}: ${JSON.stringify(message.error)}`));
      else resolve(message.result);
    });
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    ws.send(JSON.stringify(payload));
  });
}

const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
const page = (method, params) => send(method, params, sessionId);
await page('Page.enable');
await page('Runtime.enable');
await page('Network.enable');

async function evaluate(expression) {
  const result = await page('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.exceptionDetails) {
    throw new Error(result.exceptionDetails.text + ' ' + (result.exceptionDetails.exception?.description ?? ''));
  }
  return result.result.value;
}

async function shot(name) {
  const { data } = await page('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true });
  await writeFile(new URL(`../${name}`, import.meta.url), Buffer.from(data, 'base64'));
}

async function setViewport(width, height) {
  await page('Emulation.setDeviceMetricsOverride', {
    width,
    height,
    deviceScaleFactor: 1,
    mobile: width < 768,
  });
}

try {
  await setViewport(1280, 1100);
  await page('Page.navigate', { url: 'http://localhost:9350/' });
  const ready = await evaluate(`new Promise((resolve) => {
    const start = Date.now();
    const id = setInterval(() => {
      if (document.querySelector('.d-board') || Date.now() - start > 8000) {
        clearInterval(id);
        resolve(Boolean(document.querySelector('.d-board')));
      }
    }, 50);
  })`);
  if (!ready) {
    const diag = await evaluate(`(() => ({ href: location.href, title: document.title, text: document.body?.innerText?.slice(0, 500), html: document.body?.innerHTML?.slice(0, 500) }))()`);
    throw new Error(`board missing ${JSON.stringify(diag)}`);
  }
  await evaluate('document.fonts.ready');

  const initial = await evaluate(`(() => {
    const hours = [0, 7, 8, 22].map((hour) => {
      const nodes = [...document.querySelectorAll('[data-layout="desktop"] [data-hour="' + hour + '"]')];
      const xs = nodes.map((node) => Math.round(node.getBoundingClientRect().x));
      return {
        hour,
        count: nodes.length,
        uniqueX: [...new Set(xs)],
        states: nodes.filter((node) => node.dataset.city).map((node) => node.dataset.city + ':' + node.dataset.state),
      };
    });
    const cities = [...document.querySelectorAll('[data-layout="desktop"] [data-city]')].map((node) => ({
      id: node.dataset.city,
      ref: node.dataset.ref,
      y: Math.round(node.getBoundingClientRect().y),
      text: node.innerText,
    }));
    const board = document.querySelector('.d-board').getBoundingClientRect();
    const removes = [...document.querySelectorAll('.d-remove')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { left: Math.round(rect.left), right: Math.round(rect.right), top: Math.round(rect.top), boardRight: Math.round(board.right) };
    });
    const overlap = getComputedStyle(document.querySelector('[data-state="overlap"]'));
    const sleep = getComputedStyle(document.querySelector('[data-state="sleep"]'));
    const awake = getComputedStyle(document.querySelector('[data-state="awake"]'));
    return {
      title: document.title,
      h1: document.querySelector('h1')?.textContent,
      hint: document.querySelector('.hint')?.textContent,
      summary: document.querySelector('.summary')?.innerText,
      mode: document.querySelector('.app')?.dataset.mode,
      layout: document.querySelector('.app')?.dataset.layout,
      mobileMounted: Boolean(document.querySelector('.m-board')),
      cities,
      hours,
      removes,
      colors: { overlap: overlap.backgroundColor, sleep: sleep.backgroundColor, awake: awake.backgroundColor, overlapWeight: overlap.fontWeight },
      storage: localStorage.getItem('tz-overlap.v1'),
    };
  })()`);

  assert(initial.title === 'Grok 4.7', `title ${initial.title}`);
  assert(initial.h1 === 'Grok 4.7', `h1 ${initial.h1}`);
  assert(initial.hint === 'Green cells = everyone awake', `hint ${initial.hint}`);
  assert(initial.mode === 'meeting', `mode ${initial.mode}`);
  assert(initial.layout === 'desktop', `layout ${initial.layout}`);
  assert(initial.mobileMounted === false, 'mobile board hidden on desktop');
  assert(initial.summary.includes('2 shared hours'), `summary ${initial.summary}`);
  assert(initial.summary.includes('7am — 8am'), `summary ranges ${initial.summary}`);
  assert(initial.summary.includes('10pm — 11pm'), `summary late range ${initial.summary}`);
  assert(initial.summary.includes('San Francisco time'), `summary zone ${initial.summary}`);
  assert(initial.cities.map((city) => city.id).join(',') === 'san-francisco,denpasar,geneva', `cities ${initial.cities.map((c) => c.id)}`);
  assert(initial.cities[0].ref === 'true', 'first city is reference');
  assert(initial.cities[0].text.includes('REF'), 'REF badge');
  assert(initial.cities[0].text.includes('UTC−7') || initial.cities[0].text.includes('UTC-7'), `offset ${initial.cities[0].text}`);
  assert(initial.cities[1].text.includes('UTC+8'), `denpasar offset ${initial.cities[1].text}`);
  assert(initial.cities[2].text.includes('UTC+2'), `geneva offset ${initial.cities[2].text}`);
  assert(initial.cities[0].y < initial.cities[1].y && initial.cities[1].y < initial.cities[2].y, 'cities stack vertically');
  for (const hour of initial.hours) {
    assert(hour.count === 4, `hour ${hour.hour} node count ${hour.count}`);
    assert(hour.uniqueX.length === 1, `hour ${hour.hour} x ${hour.uniqueX.join(',')}`);
  }
  const overlap7 = initial.hours.find((hour) => hour.hour === 7);
  assert(overlap7.states.every((state) => state.endsWith(':overlap')), `hour 7 states ${overlap7.states}`);
  const awake8 = initial.hours.find((hour) => hour.hour === 8);
  assert(awake8.states.includes('san-francisco:awake'), `hour 8 ${awake8.states}`);
  assert(awake8.states.includes('denpasar:sleep'), `hour 8 dps ${awake8.states}`);
  assert(initial.colors.overlap !== initial.colors.sleep && initial.colors.overlap !== initial.colors.awake, `colors ${JSON.stringify(initial.colors)}`);
  assert(initial.storage.includes('san-francisco'), `storage ${initial.storage}`);
  for (const button of initial.removes) {
    assert(button.right <= button.boardRight + 1 && button.left >= 0, `remove visible ${JSON.stringify(button)}`);
  }
  await shot('verify-desktop.png');

  await evaluate(`(() => {
    document.querySelector('[data-city="geneva"]').click();
  })()`);
  await delay(50);
  const promoted = await evaluate(`(() => ({
    cities: [...document.querySelectorAll('[data-layout="desktop"] [data-city]')].map((node) => node.dataset.city),
    summary: document.querySelector('.summary')?.innerText,
    ref: document.querySelector('[data-ref="true"]')?.dataset.city,
  }))()`);
  assert(promoted.cities[0] === 'geneva' && promoted.ref === 'geneva', `promoted ${promoted.cities}`);
  assert(promoted.summary.includes('Geneva time'), `promoted summary ${promoted.summary}`);
  assert(promoted.summary.includes('2 shared hours'), `promoted count ${promoted.summary}`);

  await evaluate(`(() => {
    [...document.querySelectorAll('[role="radio"]')].find((button) => button.textContent.includes('Base')).click();
  })()`);
  await delay(50);
  const base = await evaluate(`(() => ({
    mode: document.querySelector('.app').dataset.mode,
    hint: document.querySelector('.hint').textContent,
    summary: document.querySelector('.summary').innerText,
    refOverlap: [...document.querySelectorAll('[data-city="geneva"] ~ [data-city="geneva"], [data-layout="desktop"] [data-city="geneva"]')].length,
    states: [7, 8].map((hour) => [...document.querySelectorAll('[data-hour="' + hour + '"]')]
      .filter((node) => node.dataset.city)
      .map((node) => node.dataset.city + ':' + node.dataset.state)),
  }))()`);
  assert(base.mode === 'base', 'base mode');
  assert(base.hint === 'Green cells = awake together with Geneva', `base hint ${base.hint}`);
  assert(base.summary.includes('Denpasar'), `base summary ${base.summary}`);
  assert(base.summary.includes('San Francisco'), `base summary sf ${base.summary}`);
  assert(base.states[0].find((item) => item.startsWith('geneva:')).endsWith(':awake') || base.states[0].find((item) => item.startsWith('geneva:')).endsWith(':sleep'), `ref not forced overlap ${base.states}`);
  assert(!base.states.flat().some((item) => item.startsWith('geneva:') && item.endsWith(':overlap')), `reference stays unhighlighted ${base.states}`);
  const denpasar8 = base.states[1].find((item) => item.startsWith('denpasar:'));
  const sf8 = base.states[1].find((item) => item.startsWith('san-francisco:'));
  assert(denpasar8 !== sf8, `base cities differ at hour 8 ${base.states[1]}`);
  await shot('verify-base.png');

  await evaluate(`(() => {
    const input = document.querySelector('input[role="combobox"]');
    const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value').set;
    setter.call(input, 'mumbai');
    input.dispatchEvent(new Event('input', { bubbles: true }));
  })()`);
  await delay(80);
  const search = await evaluate(`(() => ({
    open: document.querySelector('input').getAttribute('aria-expanded'),
    options: [...document.querySelectorAll('[role="option"]')].map((node) => node.innerText),
  }))()`);
  assert(search.open === 'true', 'menu open');
  assert(search.options.some((option) => option.includes('Mumbai') && option.includes('UTC+5:30')), `mumbai option ${search.options}`);
  await evaluate(`document.querySelector('[role="option"]').click()`);
  await delay(50);
  const added = await evaluate(`(() => {
    const cell = document.querySelector('[data-city="mumbai"][data-minute="30"]');
    return {
      cities: [...document.querySelectorAll('[data-layout="desktop"] [data-city]')].map((node) => node.dataset.city),
      minute: cell?.dataset.minute ?? null,
      text: cell?.innerText ?? null,
      dup: document.querySelectorAll('[data-city="mumbai"]').length,
    };
  })()`);
  assert(added.cities.includes('mumbai'), `added ${added.cities}`);
  assert(added.minute === '30', `fractional minute ${added.minute} ${added.text}`);
  assert(added.dup === 1, `no duplicate mumbai rows ${added.dup}`);
  await shot('verify-mumbai.png');

  await evaluate(`(() => {
    [...document.querySelectorAll('.format-toggle [role="radio"]')].find((button) => button.textContent.trim() === '24h').click();
  })()`);
  await delay(40);
  const formatted = await evaluate(`document.querySelector('.summary').innerText`);
  assert(formatted.includes('—'), `24h summary ${formatted}`);
  assert(/\d{2}:\d{2}/.test(formatted), `24h clock ${formatted}`);

  await page('Page.reload', { ignoreCache: true });
  await evaluate(`new Promise((resolve) => {
    const start = Date.now();
    const id = setInterval(() => {
      if (document.querySelector('[data-city="mumbai"]') || Date.now() - start > 8000) {
        clearInterval(id);
        resolve(true);
      }
    }, 50);
  })`);
  const restored = await evaluate(`(() => ({
    mode: document.querySelector('.app').dataset.mode,
    cities: [...document.querySelectorAll('[data-city]')].map((node) => node.dataset.city),
    summary: document.querySelector('.summary')?.innerText,
    checked: document.querySelector('.format-toggle [aria-checked="true"]')?.textContent,
  }))()`);
  assert(restored.mode === 'base', `restored mode ${restored.mode}`);
  assert(restored.cities[0] === 'geneva', `restored ref ${restored.cities}`);
  assert(restored.cities.includes('mumbai'), `restored mumbai ${restored.cities}`);
  assert(restored.checked?.includes('24h'), `restored format ${restored.checked}`);

  await setViewport(390, 844);
  await delay(100);
  const mobile = await evaluate(`(() => {
    const board = document.querySelector('.m-board');
    const cities = [...document.querySelectorAll('[data-layout="mobile"] [data-city]')];
    const hour0 = [...document.querySelectorAll('[data-layout="mobile"] [data-hour="0"]')];
    const hour1 = [...document.querySelectorAll('[data-layout="mobile"] [data-hour="1"]')];
    const cityXs = cities.map((node) => Math.round(node.getBoundingClientRect().x));
    const hour0ys = hour0.map((node) => Math.round(node.getBoundingClientRect().y));
    return {
      layout: document.querySelector('.app').dataset.layout,
      desktop: Boolean(document.querySelector('.d-board')),
      mobile: Boolean(board),
      hint: document.querySelector('.hint').textContent,
      cityXs,
      cityYs: cities.map((node) => Math.round(node.getBoundingClientRect().y)),
      hour0ys,
      hour1y: hour1[0] ? Math.round(hour1[0].getBoundingClientRect().y) : null,
      hour0xSpread: [...new Set(hour0.filter((node) => node.dataset.city).map((node) => Math.round(node.getBoundingClientRect().y)))],
    };
  })()`);
  assert(mobile.layout === 'mobile', `mobile layout attr ${mobile.layout}`);
  assert(mobile.desktop === false && mobile.mobile === true, 'only mobile board mounted');
  assert(mobile.cityXs[0] < mobile.cityXs[1] && mobile.cityXs[1] < mobile.cityXs[2], `cities are columns ${mobile.cityXs}`);
  assert(new Set(mobile.cityYs).size === 1, `city headers share a row ${mobile.cityYs}`);
  assert(mobile.hour1y > mobile.hour0ys[0], `hours stack ${mobile.hour0ys[0]} -> ${mobile.hour1y}`);
  assert(mobile.hour0xSpread.length === 1, `same hour shares a row ${mobile.hour0xSpread}`);
  assert(mobile.hint.includes('Green cells'), `mobile hint ${mobile.hint}`);
  await shot('verify-mobile.png');

  await evaluate(`document.querySelector('[aria-label="Remove Mumbai"]').click()`);
  await delay(40);
  const removed = await evaluate(`document.querySelectorAll('[data-city="mumbai"]').length`);
  assert(removed === 0, `removed mumbai ${removed}`);

  console.log(JSON.stringify({ failures, exceptions, logs, initialSummary: initial.summary, colors: initial.colors, removes: initial.removes }, null, 2));
} finally {
  chrome.kill();
  ws.close();
  await rm(profile, { recursive: true, force: true });
}

if (failures.length || exceptions.length) {
  process.exit(1);
}

import { spawn } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { setTimeout as delay } from 'node:timers/promises';

const chromePath = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';
const profile = await mkdtemp(join(tmpdir(), 'tz-chrome-'));
const port = 9342;
const chrome = spawn(chromePath, [
  '--headless=new', '--disable-gpu', '--no-first-run', '--no-default-browser-check',
  `--remote-debugging-port=${port}`, `--user-data-dir=${profile}`, 'about:blank',
], { stdio: 'ignore' });

async function waitJson(url) {
  for (let i = 0; i < 50; i += 1) {
    try {
      const response = await fetch(url);
      if (response.ok) return await response.json();
    } catch { /* booting */ }
    await delay(100);
  }
  throw new Error('chrome timeout');
}

const version = await waitJson(`http://127.0.0.1:${port}/json/version`);
const ws = new WebSocket(version.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
let seq = 0;
const pending = new Map();
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
});
function send(method, params = {}, sessionId) {
  const id = ++seq;
  return new Promise((resolve, reject) => {
    pending.set(id, (message) => {
      if (message.error) reject(new Error(`${method} ${JSON.stringify(message.error)}`));
      else resolve(message.result);
    });
    const payload = { id, method, params };
    if (sessionId) payload.sessionId = sessionId;
    ws.send(JSON.stringify(payload));
  });
}
const { targetId } = await send('Target.createTarget', { url: 'about:blank' });
const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true });
const page = (method, params) => send(method, params, sessionId);
await page('Page.enable');
await page('Runtime.enable');
async function evaluate(expression) {
  const result = await page('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (result.exceptionDetails) throw new Error(result.exceptionDetails.exception?.description || result.exceptionDetails.text);
  return result.result.value;
}
async function shot(name) {
  const { data } = await page('Page.captureScreenshot', { format: 'png', captureBeyondViewport: true });
  await writeFile(new URL(`../${name}`, import.meta.url), Buffer.from(data, 'base64'));
}
async function viewport(width, height) {
  await page('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: width < 768 });
}

const report = {};
try {
  await viewport(820, 900);
  await page('Page.navigate', { url: 'http://localhost:9350/' });
  await evaluate(`new Promise((resolve) => {
    const start = Date.now();
    const id = setInterval(() => {
      if (document.querySelector('.cell[data-state="overlap"]') || Date.now() - start > 8000) {
        clearInterval(id); resolve(true);
      }
    }, 40);
  })`);
  report.narrow = await evaluate(`(() => {
    const board = document.querySelector('.d-board');
    const boardRect = board.getBoundingClientRect();
    const hours = [...document.querySelectorAll('.d-hour')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { hour: Number(node.dataset.hour), left: Math.round(rect.left), right: Math.round(rect.right), visible: rect.right > boardRect.left + 8 && rect.left < boardRect.right - 8 };
    });
    const removes = [...document.querySelectorAll('.d-remove')].map((node) => {
      const rect = node.getBoundingClientRect();
      return { left: Math.round(rect.left), right: Math.round(rect.right), inBoard: rect.left >= boardRect.left && rect.right <= boardRect.right + 1 };
    });
    const overlap = getComputedStyle(document.querySelector('.cell[data-state="overlap"]'));
    const sleep = getComputedStyle(document.querySelector('.cell[data-state="sleep"]'));
    const awake = getComputedStyle(document.querySelector('.cell[data-state="awake"]'));
    return {
      board: { width: Math.round(boardRect.width), scroll: board.scrollWidth, client: board.clientWidth },
      visibleHours: hours.filter((hour) => hour.visible).map((hour) => hour.hour),
      hiddenHours: hours.filter((hour) => !hour.visible).map((hour) => hour.hour),
      removes,
      colors: { overlap: overlap.backgroundColor, sleep: sleep.backgroundColor, awake: awake.backgroundColor, overlapColor: overlap.color },
      hourCount: document.querySelectorAll('.d-hour').length,
      cellCount: document.querySelectorAll('.d-board .cell').length,
    };
  })()`);
  await shot('verify-narrow.png');

  await viewport(390, 844);
  await delay(80);
  report.mobile = await evaluate(`(() => {
    const board = document.querySelector('.m-board');
    const hours = [...document.querySelectorAll('.m-hour')];
    const cities = [...document.querySelectorAll('.m-city')];
    const ys = hours.map((node) => Math.round(node.getBoundingClientRect().y));
    const cityBoxes = cities.map((node) => {
      const rect = node.getBoundingClientRect();
      const name = node.querySelector('.city-name');
      return {
        id: node.dataset.city,
        text: name?.textContent,
        width: Math.round(rect.width),
        nameScroll: name?.scrollWidth,
        nameClient: name?.clientWidth,
        x: Math.round(rect.x),
      };
    });
    return {
      desktop: Boolean(document.querySelector('.d-board')),
      hourCount: hours.length,
      increasing: ys.every((y, index) => index === 0 || y > ys[index - 1]),
      firstY: ys[0],
      lastY: ys.at(-1),
      cityBoxes,
      boardScroll: board.scrollWidth,
      boardClient: board.clientWidth,
      hint: document.querySelector('.hint')?.textContent,
      title: document.title,
    };
  })()`);
  await shot('verify-mobile-default.png');

  await evaluate('window.scrollTo(0, 900)');
  await delay(50);
  report.stuck = await evaluate(`(() => {
    const header = document.querySelector('.m-city');
    const hour = document.querySelector('.m-hour[data-hour="18"]');
    return {
      headerTop: Math.round(header.getBoundingClientRect().top),
      hour18Top: hour ? Math.round(hour.getBoundingClientRect().top) : null,
      scrollY: Math.round(window.scrollY),
    };
  })()`);
  await shot('verify-mobile-scrolled.png');
  console.log(JSON.stringify(report, null, 2));
} finally {
  chrome.kill();
  ws.close();
  await rm(profile, { recursive: true, force: true }).catch(() => {});
}
